-- Run in a new Supabase project. Admins must be assigned by a trusted operator.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade, name text not null check(length(name) between 1 and 100), role text not null check(role in ('worker','employer','admin')), language text not null default 'en-IN', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.worker_profiles(id uuid primary key references public.profiles on delete cascade, skills text[] not null default '{}', phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.employer_profiles(id uuid primary key references public.profiles on delete cascade, business_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.jobs(id uuid primary key default gen_random_uuid(), employer_id uuid not null references public.profiles on delete cascade, title text not null check(length(title) between 1 and 120), employer text not null check(length(employer) between 1 and 120), category text not null, area text not null, lat double precision not null check(lat between -90 and 90), lng double precision not null check(lng between -180 and 180), wage integer not null check(wage>0), frequency text not null check(frequency in ('daily','monthly')), type text not null check(type in ('Full-time','Part-time','Contract')), hours text not null, skills text[] not null default '{}', description text not null check(length(description) between 10 and 5000), vacancies integer not null check(vacancies between 1 and 1000), status text not null default 'open' check(status in ('open','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.applications(id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs on delete cascade, worker_id uuid not null references public.profiles on delete cascade, worker_name text not null, status text not null default 'Submitted' check(status in ('Submitted','Shortlisted','Accepted','Declined')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(job_id,worker_id));
create table public.saved_jobs(worker_id uuid references public.profiles on delete cascade, job_id uuid references public.jobs on delete cascade, created_at timestamptz not null default now(), primary key(worker_id,job_id));
create table public.verification_documents(id uuid primary key default gen_random_uuid(), worker_id uuid not null references public.profiles on delete cascade, document_type text not null check(document_type in ('Skill certificate','Training certificate','Identity document (redacted)')), storage_path text not null unique, consent_at timestamptz not null, status text not null default 'Pending Review' check(status in ('Pending Review','Verified','Rejected')), feedback text, reviewed_by uuid references public.profiles, reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index verification_one_pending on public.verification_documents(worker_id) where status='Pending Review';
create table public.contact_messages(id uuid primary key default gen_random_uuid(), name text not null, email text not null, phone text, subject text not null, message text not null, created_at timestamptz not null default now());
create table public.job_reports(id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs on delete cascade, reporter_id uuid not null references public.profiles on delete cascade, reason text not null check(length(reason) between 1 and 1000), status text not null default 'open' check(status in ('open','resolved')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.api_limits(bucket text primary key, hits integer not null default 1, window_start timestamptz not null default now());
create index jobs_search on public.jobs(status,category,created_at desc);create index jobs_location on public.jobs(lat,lng);create index applications_worker on public.applications(worker_id);create index verification_worker on public.verification_documents(worker_id,created_at desc);create index jobs_employer on public.jobs(employer_id);
create or replace function public.current_role_name() returns text language sql stable security definer set search_path='' as $$ select role from public.profiles where id=auth.uid() $$;
revoke all on function public.current_role_name() from public;grant execute on function public.current_role_name() to authenticated;
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,name,role) values(new.id,left(coalesce(nullif(new.raw_user_meta_data->>'name',''),'New user'),100),case when new.raw_user_meta_data->>'role'='employer' then 'employer' else 'worker' end);return new;end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_profile();
create or replace function public.touch_updated() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;
do $$declare t text;begin foreach t in array array['profiles','worker_profiles','employer_profiles','jobs','applications','verification_documents','job_reports'] loop execute format('create trigger touch_updated before update on public.%I for each row execute function public.touch_updated()',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['profiles','worker_profiles','employer_profiles','jobs','applications','saved_jobs','verification_documents','contact_messages','job_reports','api_limits'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
-- Column privileges are essential: users cannot change their role, owner IDs, or verification outcome.
revoke all on all tables in schema public from anon,authenticated;
grant select on public.jobs to anon,authenticated;
grant select on public.profiles,public.worker_profiles,public.employer_profiles,public.applications,public.saved_jobs,public.verification_documents,public.contact_messages,public.job_reports to authenticated;
grant update(name,language) on public.profiles to authenticated;
grant insert(id,skills,phone),update(skills,phone) on public.worker_profiles to authenticated;
grant insert(id,business_name),update(business_name) on public.employer_profiles to authenticated;
grant insert(employer_id,title,employer,category,area,lat,lng,wage,frequency,type,hours,skills,description,vacancies,status),update(title,employer,category,area,lat,lng,wage,frequency,type,hours,skills,description,vacancies,status) on public.jobs to authenticated;
grant insert(job_id,worker_id,worker_name,status),update(status) on public.applications to authenticated;
grant insert(worker_id,job_id),delete on public.saved_jobs to authenticated;
grant insert(worker_id,document_type,storage_path,consent_at),update(status,feedback,reviewed_by,reviewed_at) on public.verification_documents to authenticated;
grant insert(job_id,reporter_id,reason),update(status) on public.job_reports to authenticated;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or public.current_role_name()='admin');
create policy profile_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy worker_profile_owner on public.worker_profiles for all to authenticated using(id=auth.uid() and public.current_role_name()='worker') with check(id=auth.uid() and public.current_role_name()='worker');
create policy employer_profile_owner on public.employer_profiles for all to authenticated using(id=auth.uid() and public.current_role_name()='employer') with check(id=auth.uid() and public.current_role_name()='employer');
create policy jobs_public on public.jobs for select to anon,authenticated using(status='open');
create policy jobs_private on public.jobs for select to authenticated using(employer_id=auth.uid() or public.current_role_name()='admin');
create policy jobs_insert on public.jobs for insert to authenticated with check(employer_id=auth.uid() and public.current_role_name()='employer');
create policy jobs_update on public.jobs for update to authenticated using((employer_id=auth.uid() and public.current_role_name()='employer') or public.current_role_name()='admin') with check((employer_id=auth.uid() and public.current_role_name()='employer') or public.current_role_name()='admin');
create policy apps_read on public.applications for select to authenticated using(worker_id=auth.uid() or exists(select 1 from public.jobs j where j.id=job_id and j.employer_id=auth.uid()) or public.current_role_name()='admin');
create policy apps_insert on public.applications for insert to authenticated with check(worker_id=auth.uid() and public.current_role_name()='worker' and status='Submitted' and exists(select 1 from public.jobs j where j.id=job_id and j.status='open') and worker_name=(select name from public.profiles where id=auth.uid()));
create policy apps_update on public.applications for update to authenticated using(public.current_role_name()='employer' and exists(select 1 from public.jobs j where j.id=job_id and j.employer_id=auth.uid())) with check(public.current_role_name()='employer' and exists(select 1 from public.jobs j where j.id=job_id and j.employer_id=auth.uid()));
create policy saves_owner on public.saved_jobs for all to authenticated using(worker_id=auth.uid() and public.current_role_name()='worker') with check(worker_id=auth.uid() and public.current_role_name()='worker');
create policy docs_read on public.verification_documents for select to authenticated using(worker_id=auth.uid() or public.current_role_name()='admin');
create policy docs_insert on public.verification_documents for insert to authenticated with check(worker_id=auth.uid() and public.current_role_name()='worker' and status='Pending Review' and split_part(storage_path,'/',1)=auth.uid()::text and exists(select 1 from storage.objects where bucket_id='verification' and name=storage_path));
create policy docs_admin on public.verification_documents for update to authenticated using(public.current_role_name()='admin' and status='Pending Review') with check(public.current_role_name()='admin' and status in ('Verified','Rejected') and reviewed_by=auth.uid() and reviewed_at is not null);
create policy messages_admin on public.contact_messages for select to authenticated using(public.current_role_name()='admin');
create policy reports_insert on public.job_reports for insert to authenticated with check(reporter_id=auth.uid() and status='open');
create policy reports_read on public.job_reports for select to authenticated using(reporter_id=auth.uid() or public.current_role_name()='admin');
create policy reports_admin on public.job_reports for update to authenticated using(public.current_role_name()='admin') with check(public.current_role_name()='admin');
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('verification','verification',false,5242880,array['application/pdf','image/png','image/jpeg']) on conflict(id) do nothing;
create policy verification_upload on storage.objects for insert to authenticated with check(bucket_id='verification' and (storage.foldername(name))[1]=auth.uid()::text and public.current_role_name()='worker');
create policy verification_read on storage.objects for select to authenticated using(bucket_id='verification' and ((storage.foldername(name))[1]=auth.uid()::text or public.current_role_name()='admin'));
create policy verification_remove_orphan on storage.objects for delete to authenticated using(bucket_id='verification' and (storage.foldername(name))[1]=auth.uid()::text and not exists(select 1 from public.verification_documents d where d.storage_path=name));
create or replace function public.consume_limit(p_bucket text,p_max integer) returns boolean language plpgsql security definer set search_path='' as $$declare n integer;begin insert into public.api_limits(bucket) values(p_bucket) on conflict(bucket) do update set hits=case when public.api_limits.window_start<now()-interval '1 minute' then 1 else public.api_limits.hits+1 end,window_start=case when public.api_limits.window_start<now()-interval '1 minute' then now() else public.api_limits.window_start end returning hits into n;return n<=p_max;end$$;
revoke all on function public.consume_limit(text,integer) from public,anon,authenticated;grant execute on function public.consume_limit(text,integer) to service_role;
-- Share only the latest review status, never the document or its storage path,
-- with the employer who owns a job to which the worker applied.
create or replace function public.applicant_verification_status() returns table(worker_id uuid,status text) language sql stable security definer set search_path='' as $$
select distinct a.worker_id,coalesce((select d.status from public.verification_documents d where d.worker_id=a.worker_id order by d.created_at desc limit 1),'Not Submitted') from public.applications a join public.jobs j on j.id=a.job_id where j.employer_id=auth.uid() and public.current_role_name()='employer' $$;
revoke all on function public.applicant_verification_status() from public,anon;grant execute on function public.applicant_verification_status() to authenticated;
